// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value) public {
        _value = bound(_value, 1, type(uint128).max);

        Reverter target = new Reverter();

        vm.deal(address(c), _value * 2);

        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        c.sendMoney(address(target), _value);
        uint256 balanceAfter = address(c).balance;

        assertEq(balanceBefore, balanceAfter);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
